//! 🧪️ Genuine original Host currency cannot renew itself or admit a second owner before exact receipt collection.
use super::*;
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_host_wake_ledger_keeps_actual_turn_exclusion_all_currencies_and_explicit_driver_return(){
 let(_,heap)=observe(||drop(vec![0u8;37]));assert_eq!(heap,(37,37));
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["policy"];let grant=RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:p["release"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize};let ledger=GuestRelayWakeReceiptLedger::new();let pointer=&ledger as*const GuestRelayWakeReceiptLedger;
 let(context,heap)=observe(||ledger.checkout(7,3).unwrap());assert!(context.is_none());assert_eq!(heap,(0,0));
 assert!(ledger.begin_turn(70,grant).unwrap());let context=ledger.checkout(7,3).unwrap().unwrap();let zero=GuestRelayWakeReceipt{epoch:context.epoch,slot:7,generation:3,grant:context.grant,progress:Default::default()};let(collected,heap)=observe(||ledger.collect(&zero).unwrap());assert!(collected);assert_eq!(heap,(0,0));let returned=ledger.take_turn(70).unwrap().unwrap();assert_eq!(returned.remaining,grant);assert_eq!(returned.spent,Default::default());let(replayed,heap)=observe(||ledger.begin_turn(70,grant));assert!(replayed.is_err());assert_eq!(heap,(0,0));
 let held=ledger.original.try_lock().unwrap();let(context,heap)=observe(||ledger.checkout(7,3).unwrap());assert!(context.is_none());assert_eq!(heap,(0,0));let(collected,heap)=observe(||ledger.collect(&zero).unwrap());assert!(!collected);assert_eq!(heap,(0,0));drop(held);
 for (phase,row)in law["receipts"].as_array().unwrap().iter().enumerate(){let epoch=71+phase as u64;let(admitted,heap)=observe(||ledger.begin_turn(epoch,grant).unwrap());assert!(admitted);assert_eq!(heap,(0,0));let(context,heap)=observe(||ledger.checkout(7,3).unwrap().unwrap());assert_eq!(context,GuestRelayWakeTurnGrant{epoch,grant});assert_eq!(heap,(0,0));let(context,heap)=observe(||ledger.checkout(9,5).unwrap());assert!(context.is_none());assert_eq!(heap,(0,0));let(returned,heap)=observe(||ledger.take_turn(epoch).unwrap());assert!(returned.is_none());assert_eq!(heap,(0,0));
 let receipt=GuestRelayWakeReceipt{epoch,slot:7,generation:3,grant,progress:RetainedCloneProgress{copied_items:row["copiedItems"].as_u64().unwrap()as usize,copied_bytes:row["copiedBytes"].as_u64().unwrap()as usize,retained_capacity_bytes:row["retainedCapacityBytes"].as_u64().unwrap()as usize,released_bytes:row["releasedBytes"].as_u64().unwrap()as usize}};
 for denied in [GuestRelayWakeReceipt{epoch:epoch+1,..receipt},GuestRelayWakeReceipt{slot:9,..receipt},GuestRelayWakeReceipt{generation:5,..receipt},GuestRelayWakeReceipt{progress:RetainedCloneProgress{copied_items:2,..receipt.progress},..receipt},GuestRelayWakeReceipt{progress:RetainedCloneProgress{copied_bytes:4097,..receipt.progress},..receipt},GuestRelayWakeReceipt{progress:RetainedCloneProgress{retained_capacity_bytes:65537,..receipt.progress},..receipt},GuestRelayWakeReceipt{progress:RetainedCloneProgress{released_bytes:262145,..receipt.progress},..receipt},GuestRelayWakeReceipt{grant:RetainedCloneGrant{maximum_depth:65,..grant},..receipt}]{let(result,heap)=observe(||ledger.collect(&denied));assert!(result.is_err());assert_eq!(heap,(0,0));assert_eq!(&ledger as*const _,pointer);}
 let(collected,heap)=observe(||ledger.collect(&receipt).unwrap());assert!(collected);assert_eq!(heap,(0,0));let(duplicate,heap)=observe(||ledger.collect(&receipt));assert!(duplicate.is_err());assert_eq!(heap,(0,0));let(context,heap)=observe(||ledger.checkout(7,3).unwrap());assert!(context.is_none());assert_eq!(heap,(0,0));let(renewed,heap)=observe(||ledger.begin_turn(epoch+1,grant).unwrap());assert!(!renewed);assert_eq!(heap,(0,0));let(returned,heap)=observe(||ledger.take_turn(epoch).unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(returned.original,grant);assert_eq!(returned.spent,receipt.progress);assert_eq!(returned.remaining.maximum_items,0);assert_eq!(returned.remaining.maximum_copy_bytes,grant.maximum_copy_bytes-receipt.progress.copied_bytes);assert_eq!(returned.remaining.maximum_capacity_bytes,grant.maximum_capacity_bytes-receipt.progress.retained_capacity_bytes);assert_eq!(returned.remaining.maximum_release_bytes,grant.maximum_release_bytes-receipt.progress.released_bytes);assert_eq!(returned.remaining.maximum_depth,grant.maximum_depth);}
 let(_,heap)=observe(||drop(ledger));assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original Host wake context2explicitdriverturns no initial/automatic grant simultaneoussecondcheckout denied all4currency+depth+epoch+slot+generation overspend denied heap0 duplicate receipt rejected held exact original then full spent/remaining returned terminalDrop0");
}
